#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "mol/m³".parse::<MolarityUnit>(),
        Ok(MolarityUnit::MolePerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "mol/m³").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::MolePerCubicMeter))
    );
    assert_eq!(
        "kmol/m³".parse::<MolarityUnit>(),
        Ok(MolarityUnit::KilomolePerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "kmol/m³").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::KilomolePerCubicMeter))
    );
    assert_eq!(
        "mol/l".parse::<MolarityUnit>(),
        Ok(MolarityUnit::MolePerLiter)
    );
    assert_eq!(
        format!("2.5 {}", "mol/l").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::MolePerLiter))
    );
    assert_eq!("M".parse::<MolarityUnit>(), Ok(MolarityUnit::MolePerLiter));
    assert_eq!(
        format!("2.5 {}", "M").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::MolePerLiter))
    );
    assert_eq!(
        "fmol/l".parse::<MolarityUnit>(),
        Ok(MolarityUnit::FemtomolePerLiter)
    );
    assert_eq!(
        format!("2.5 {}", "fmol/l").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::FemtomolePerLiter))
    );
    assert_eq!(
        "pmol/l".parse::<MolarityUnit>(),
        Ok(MolarityUnit::PicomolePerLiter)
    );
    assert_eq!(
        format!("2.5 {}", "pmol/l").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::PicomolePerLiter))
    );
    assert_eq!(
        "nmol/l".parse::<MolarityUnit>(),
        Ok(MolarityUnit::NanomolePerLiter)
    );
    assert_eq!(
        format!("2.5 {}", "nmol/l").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::NanomolePerLiter))
    );
    assert_eq!(
        "µmol/l".parse::<MolarityUnit>(),
        Ok(MolarityUnit::MicromolePerLiter)
    );
    assert_eq!(
        format!("2.5 {}", "µmol/l").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::MicromolePerLiter))
    );
    assert_eq!(
        "mmol/l".parse::<MolarityUnit>(),
        Ok(MolarityUnit::MillimolePerLiter)
    );
    assert_eq!(
        format!("2.5 {}", "mmol/l").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::MillimolePerLiter))
    );
    assert_eq!(
        "cmol/l".parse::<MolarityUnit>(),
        Ok(MolarityUnit::CentimolePerLiter)
    );
    assert_eq!(
        format!("2.5 {}", "cmol/l").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::CentimolePerLiter))
    );
    assert_eq!(
        "dmol/l".parse::<MolarityUnit>(),
        Ok(MolarityUnit::DecimolePerLiter)
    );
    assert_eq!(
        format!("2.5 {}", "dmol/l").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::DecimolePerLiter))
    );
    assert_eq!(
        "lbmol/ft³".parse::<MolarityUnit>(),
        Ok(MolarityUnit::PoundMolePerCubicFoot)
    );
    assert_eq!(
        format!("2.5 {}", "lbmol/ft³").parse::<Molarity>(),
        Ok(Molarity::new(2.5, MolarityUnit::PoundMolePerCubicFoot))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Molarity>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = Molarity::from_base(6.0);
    let b = Molarity::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Molarity::<i64>::from_base(7);
    let b = Molarity::<i64>::from_base(2);
    assert_eq!(a + b, Molarity::from_base(9));
    assert_eq!(a % b, Molarity::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!([a, b].iter().sum::<Molarity<i64>>(), Molarity::from_base(9));
}
